import hashlib
import json
import keyword
from collections.abc import Mapping
from importlib.resources import files
from pathlib import Path

import yaml

from guimauve.models.data import Data
from guimauve.models.model import Model, ModelError
from guimauve.models.variant import ImageVariant
from guimauve.storage.workspace import DataWorkspace

HEADER = """\
# Generated by `guimauve data sync` — DO NOT EDIT BY HAND.
# Any change will be overwritten on the next sync.
from guimauve.metaclass.metadata import MetaData
from guimauve.models.element import Element
from guimauve.models.replay import Replay

ALIAS = {alias!r}
SOURCE_HASH = {source_hash!r}
FORMAT_VERSION = {format_version!r}
"""

FORMAT_VERSION = 1

CLASS = """\


class {classname}(metaclass=MetaData, model={model}, alias=ALIAS):
{body}
"""

# --- Code generation ---


def compute_source_hash(data_file: Path) -> str:
    raw = yaml.safe_load(data_file.read_text(encoding="utf-8")) or {}
    canonical = json.dumps(raw, sort_keys=True, separators=(",", ":"), ensure_ascii=False, default=str)
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def _render_module(data: Data, alias: str, source_hash: str) -> str:
    return (
        HEADER.format(alias=alias, source_hash=source_hash, format_version=FORMAT_VERSION)
        + CLASS.format(classname="Elements", model="Element", body=_render_entries(data.elements or {}, "Element"))
        + CLASS.format(classname="Replays", model="Replay", body=_render_entries(data.replays or {}, "Replay"))
    )


def _render_entries(entries: Mapping[str, Model], model: str) -> str:
    if not entries:
        return "    pass"

    lines = []
    for name, entry in entries.items():
        if not name.isidentifier() or keyword.iskeyword(name):
            raise ValueError(f"{name!r} is not a valid Python identifier")
        dumped = entry.to_dict(json_mode=True)
        dumped["name"] = name
        lines.append(f"    {name} = {model}.from_dict({dumped!r})")

    return "\n".join(lines)


def _module_path(alias: str):
    return files("guimauve") / "data" / f"{alias}.py"


# --- Synchronisation ---


def sync_dataset(workspace: DataWorkspace, alias: str) -> ModelError | None:
    data_file = workspace.data_file(alias)
    data = Data.from_file(data_file)
    if errors := data.resolve():
        return ModelError(alias, errors)

    path = _module_path(alias)
    path.parent.mkdir(parents=True, exist_ok=True)
    _remove_orphaned_images(workspace, alias, data)
    _remove_orphaned_replays(workspace, alias, data)
    source_hash = compute_source_hash(data_file)
    path.write_text(_render_module(data, alias, source_hash), encoding="utf-8")

    return None


def sync_all(workspace: DataWorkspace) -> dict[str, ModelError]:
    aliases = set(workspace.datasets())

    data_dir = Path(str(files("guimauve") / "data"))
    if data_dir.is_dir():
        for module in data_dir.glob("*.py"):
            if module.stem != "__init__" and module.stem not in aliases:
                module.unlink()

    failures = {}
    for alias in aliases:
        if error := sync_dataset(workspace, alias):
            failures[alias] = error
    return failures


def remove_module(alias: str) -> None:
    path = _module_path(alias)
    if path.is_file():
        path.unlink()


def _remove_orphaned_images(workspace: DataWorkspace, alias: str, data: Data) -> None:
    referenced = {
        Path(variant.path).resolve()
        for element in (data.elements or {}).values()
        for variant in element.variants or []
        if isinstance(variant, ImageVariant) and variant.path is not None
    }

    images_dir = workspace.images_dir(alias)
    if not images_dir.is_dir():
        return

    # remove unreferenced files
    for path in images_dir.rglob("*"):
        if path.is_file() and path.resolve() not in referenced:
            path.unlink()

    # remove now-empty directories (deepest first)
    for path in sorted(images_dir.rglob("*"), key=lambda p: len(p.parts), reverse=True):
        if path.is_dir() and not any(path.iterdir()):
            path.rmdir()


def _remove_orphaned_replays(workspace: DataWorkspace, alias: str, data: Data) -> None:
    referenced = {Path(replay.path).resolve() for replay in (data.replays or {}).values() if replay.path is not None}

    replays_dir = workspace.replays_dir(alias)
    if not replays_dir.is_dir():
        return

    # remove unreferenced files
    for path in replays_dir.rglob("*"):
        if path.is_file() and path.resolve() not in referenced:
            path.unlink()
